import React, { useState, useEffect } from 'react';
import axios from 'axios';

const FuelPage = ({ lorryId, ownerName }) => {
  const [fuelRecords, setFuelRecords] = useState([]);
  const [newFuel, setNewFuel] = useState({
    fillDate: '',
    bunkName: '',
    totalAmount: 0,
    amountPaid: 0,
  });

  useEffect(() => {
    // Fetch fuel records when the component mounts
    axios
      .get(`/api/fuel/${lorryId}`)
      .then((response) => setFuelRecords(response.data))
      .catch((error) => console.error(error));
  }, [lorryId]);

  const handleChange = (e) => {
    setNewFuel({
      ...newFuel,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Send new fuel data to the backend
    axios
      .post('/api/fuel', { lorryId, ...newFuel })
      .then((response) => {
        setFuelRecords([...fuelRecords, newFuel]); // Update the local state with new record
        setNewFuel({
          fillDate: '',
          bunkName: '',
          totalAmount: 0,
          amountPaid: 0,
        });
      })
      .catch((error) => console.error(error));
  };

  return (
    <div>
      <div className="header-bar">
        <span>{lorryId}</span>
        <h2>{ownerName}</h2>
      </div>

      <h3>Fuel Details</h3>

      <form onSubmit={handleSubmit}>
        <input
          type="date"
          name="fillDate"
          value={newFuel.fillDate}
          onChange={handleChange}
        />
        <input
          type="text"
          name="bunkName"
          value={newFuel.bunkName}
          onChange={handleChange}
          placeholder="Bunk Name"
        />
        <input
          type="number"
          name="totalAmount"
          value={newFuel.totalAmount}
          onChange={handleChange}
          placeholder="Total Amount"
        />
        <input
          type="number"
          name="amountPaid"
          value={newFuel.amountPaid}
          onChange={handleChange}
          placeholder="Amount Paid"
        />
        <button type="submit">Add Fuel Record</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>Date</th>
            <th>Bunk Name</th>
            <th>Total Amount</th>
            <th>Amount Paid</th>
            <th>Remaining Amount</th>
          </tr>
        </thead>
        <tbody>
          {fuelRecords.map((record, index) => (
            <tr key={index}>
              <td>{record.fill_date}</td>
              <td>{record.bunk_name}</td>
              <td>{record.total_amount}</td>
              <td>{record.amount_paid}</td>
              <td>{record.remaining_amount}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default FuelPage;

import styled from 'styled-components';

const HeaderBar = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
`;

const FuelForm = styled.form`
  display: flex;
  flex-direction: column;
  margin-bottom: 20px;
  input {
    margin-bottom: 10px;
    padding: 8px;
    border-radius: 4px;
    border: 1px solid #ccc;
  }
  button {
    padding: 10px;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
  }
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  th, td {
    padding: 12px;
    text-align: center;
    border: 1px solid #ddd;
  }
`;

export { HeaderBar, FuelForm, Table };
